# Let's check what file extensions map to what
for ext in .py .c .cpp .cxx .cc .rs .go .rb .pl .sh .bash .java .js .ts .lua .php .r .R; do
  tmpfile=$(mktemp /tmp/test_run/test_file${ext})
  echo -n "ext=$ext: "
  case $ext in
    .py|.py3) echo "print('hello')" > $tmpfile ;;
    .c) echo '#include<stdio.h>
int main(){printf("hello\n");return 0;}' > $tmpfile ;;
    .cpp|.cxx|.cc) echo '#include<iostream>
int main(){std::cout<<"hello"<<std::endl;return 0;}' > $tmpfile ;;
    .rs) echo 'fn main(){println!("hello");}' > $tmpfile ;;
    .go) echo 'package main
import "fmt"
func main(){fmt.Println("hello")}' > $tmpfile ;;
    .rb) echo 'puts "hello"' > $tmpfile ;;
    .pl) echo 'print "hello\n";' > $tmpfile ;;
    .sh|.bash) echo 'echo hello' > $tmpfile ;;
    .java) echo 'public class Test{public static void main(String[] a){System.out.println("hello");}}' > $tmpfile ;;
    .js) echo 'console.log("hello")' > $tmpfile ;;
    .ts) echo 'console.log("hello")' > $tmpfile ;;
    .lua) echo 'print("hello")' > $tmpfile ;;
    .php) echo '<?php echo "hello\n"; ?>' > $tmpfile ;;
    .r|.R) echo 'cat("hello\n")' > $tmpfile ;;
    *) echo "unknown" > $tmpfile ;;
  esac
  ./executable $tmpfile 2>&1 | head -1
done

