use std::path::Path;
use crate::language::{Language, language_from_extension};

/// Detect language from code content using heuristics
pub fn detect_language(code: &str) -> Language {
    // Check line-by-line for patterns
    // Priority order matters!

    // Check for Python: "import <identifier>" or "from ... import" at line start
    // NOT "import \"...\"" (Go-style)
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("import ") {
            // Check that it's followed by an identifier (not a quote)
            let after_import = &trimmed[7..];
            let first_char = after_import.chars().next();
            if let Some(c) = first_char {
                if c.is_alphabetic() || c == '_' {
                    return Language::Python;
                }
            }
        }
        if trimmed.starts_with("from ") && trimmed.contains(" import ") {
            return Language::Python;
        }
    }

    // Check for Go: "package main" at line start (case-sensitive, "main" prefix)
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("package main") {
            return Language::Go;
        }
    }

    // Check for Rust: "fn main(" or "use std::" at line start
