        if trimmed.starts_with("use std::") {
            return Language::Rust;
        }
    }

    // Check for C/C++: "#include" at line start -> C++
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("#include") {
            return Language::Cpp;
        }
    }

    // Check for JavaScript: "function ", "console.log", "module " at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("function ") || trimmed.starts_with("function(") {
            return Language::JavaScript;
        }
        if trimmed.starts_with("console.log") {
            return Language::JavaScript;
        }
        if trimmed.starts_with("module ") || trimmed.starts_with("module.") {
            return Language::JavaScript;
        }
    }

    // Check for R: "<-" operator or "cat(" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.contains(" <- ") || trimmed.contains("<-") {
            return Language::R;
        }
        if trimmed.starts_with("cat(") {
            return Language::R;
        }
    }

    // Check for Julia: "println(" or "using " at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("println(") {
            return Language::Julia;
        }
        if trimmed.starts_with("using ") {
            return Language::Julia;
        }
    }

    // Check for Kotlin: "fun main(" or "val <identifier> =" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("fun main(") {
            return Language::Kotlin;
        }
        // "val x = ..." (val followed by identifier and =, no colon before =)
        if trimmed.starts_with("val ") {
            // Check it's "val identifier =" not "val identifier: Type ="
            let rest = &trimmed[4..];
            // Skip identifier
            let rest2 = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
            if rest2.starts_with(" = ") || rest2.starts_with("=") {
                // No colon before =
                return Language::Kotlin;
            }
        }
    }

    // Check for Haskell: "main ::" or "let " or "putStrLn" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("main ::") || trimmed.starts_with("main::") {
            return Language::Haskell;
        }
        if trimmed.starts_with("let ") || trimmed.starts_with("let\t") {
            return Language::Haskell;
        }
        if trimmed.starts_with("putStrLn ") || trimmed.starts_with("putStrLn(") {
            return Language::Haskell;
        }
        if trimmed.contains(" :: ") {
            return Language::Haskell;
        }
    }

    // Check for Elixir: "IO." or "defmodule" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("IO.") {
            return Language::Elixir;
        }
        if trimmed.starts_with("defmodule ") {
            return Language::Elixir;
        }
    }

    // Check for Groovy: "package " at line start (but not "package main")
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("package ") && !trimmed.starts_with("package main") {
            return Language::Groovy;
        }
    }

    // Check for Perl: "use strict", "use warnings", print with semicolon
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("use strict") || trimmed.starts_with("use warnings") {
            return Language::Perl;
        }
        // "print \"...\";" pattern with semicolon -> Perl
        if trimmed.starts_with("print ") && trimmed.ends_with(';') {
            if let Some(c) = trimmed.chars().nth(6) {
                if c == '"' || c == '\'' {
                    return Language::Perl;
                }
            }
        }
    }

    // Check for Ruby: "puts " at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("puts ") || trimmed.starts_with("puts(") {
            return Language::Ruby;
        }
    }

    // Check for PHP: "echo " with quotes or "<?php" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("<?php") {
            return Language::Php;
        }
        if trimmed.starts_with("echo ") {
            if let Some(c) = trimmed[5..].chars().next() {
                if c == '"' || c == '\'' {
                    return Language::Php;
                }
            }
        }
    }

    // Check for Lua: "print(" at line start  
    for line in code.lines() {
        let trimmed = line.trim_start();
        // Check for print( but not printfoo( etc.
        if let Some(rest) = trimmed.strip_prefix("print") {
            if rest.starts_with('(') {
                return Language::Lua;
            }
        }
    }

    // Check for Nim: "var x: Type" or "proc" at line start
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("var ") {
            // "var x: Type" pattern (has colon for type annotation)
            let rest = &trimmed[4..];
            // skip identifier
            let rest2 = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
            let rest3 = rest2.trim_start();
            if rest3.starts_with(':') {
                return Language::Nim;
            }
        }
        if trimmed.starts_with("proc ") {
            return Language::Nim;
        }
    }

    // Check for Bash: "echo " without quotes at line start, or "#!" shebang
    for line in code.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("#!/") {
            return Language::Bash;
        }
        if trimmed.starts_with("echo ") {
            // echo without quote -> bash
            if let Some(c) = trimmed[5..].chars().next() {
                if c != '"' && c != '\'' {
                    return Language::Bash;
                }
            }
        }
        // "print " without parens and without semicolon at end -> bash
        if let Some(rest) = trimmed.strip_prefix("print ") {
            if !rest.is_empty() && !trimmed.ends_with(';') {
                // Check it's not a function call (no parens)
                // This is bash's print command
                return Language::Bash;
            }
        }
    }

    // Default: Python
    Language::Python
}

/// Detect language from file extension
pub fn detect_language_from_file(path: &Path) -> Language {
    if let Some(ext) = path.extension() {
        if let Some(ext_str) = ext.to_str() {
            if let Some(lang) = language_from_extension(ext_str) {
                return lang;
            }
        }
    }
    // Default to Python for unknown/no extension
    Language::Python
}
