pub fn execute_stdin(lang: &Language, code: &str) -> i32 {
    match lang {
        Language::Python => {
            run_stdin_command("python3", &["-"], code)
        }
        Language::Bash => {
            run_stdin_command("bash", &["-s"], code)
        }
        Language::Perl => {
            run_stdin_command("perl", &[], code)
        }
        Language::Ruby => {
            let result = run_stdin_command_result("ruby", &[], code);
            match result {
                Ok(code) => code,
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                    eprintln!("Error: failed to start ruby for stdin execution\n\nCaused by:\n    No such file or directory (os error 2)");
                    1
                }
                Err(e) => {
                    eprintln!("Error: failed to start ruby for stdin execution\n\nCaused by:\n    {}", e);
                    1
                }
            }
        }
        Language::Rust => execute_rust_code(code),
        Language::Go => execute_go_code(code),
        Language::C => execute_c_code(code),
        Language::Cpp => execute_cpp_code(code),
        _ => execute_code(lang, code, &[]),
    }
}

fn run_command(cmd: &str, args: &[&str]) -> i32 {
    match Command::new(cmd).args(args).status() {
        Ok(status) => status.code().unwrap_or(1),
        Err(e) => {
            eprintln!("Error: {}", e);
            1
        }
    }
}

fn run_stdin_command(cmd: &str, args: &[&str], code: &str) -> i32 {
    let mut child = Command::new(cmd)
        .args(args)
        .stdin(Stdio::piped())
        .spawn()
        .unwrap_or_else(|e| {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        });

    if let Some(stdin) = child.stdin.take() {
        let mut stdin = stdin;
        let _ = stdin.write_all(code.as_bytes());
    }

    child.wait().map(|s| s.code().unwrap_or(1)).unwrap_or(1)
}

fn run_stdin_command_result(
    cmd: &str,
    args: &[&str],
    code: &str,
) -> Result<i32, std::io::Error> {
    let mut child = Command::new(cmd)
        .args(args)
        .stdin(Stdio::piped())
        .spawn()?;

    if let Some(stdin) = child.stdin.take() {
        let mut stdin = stdin;
        let _ = stdin.write_all(code.as_bytes());
    }

    Ok(child.wait()?.code().unwrap_or(1))
}

fn execute_rust_code(code: &str) -> i32 {
    let tmp_dir = match TempDir::new() {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: failed to create temp dir: {}", e);
            return 1;
        }
    };

    // Rename to run-rust... format
    let dir_path = std::env::temp_dir().join(format!("run-rust{}", rand_suffix()));
    let _ = fs::create_dir_all(&dir_path);

    let src_file = dir_path.join("main.rs");
    if let Err(e) = fs::write(&src_file, code) {
        eprintln!("Error: {}", e);
        return 1;
    }

    let bin_file = dir_path.join("main");

    // Compile
    let compile_result = Command::new("rustc")
        .arg("--edition")
        .arg("2021")
        .arg("--crate-name")
        .arg("run_snippet")
        .arg("-o")
        .arg(&bin_file)
        .arg(&src_file)
        .status();

    let _ = tmp_dir; // keep alive

    match compile_result {
        Ok(status) if status.success() => {
            let run_result = Command::new(&bin_file).status();
            let code = match run_result {
                Ok(s) => s.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            };
            let _ = fs::remove_dir_all(&dir_path);
            code
        }
        Ok(_) => {
            let _ = fs::remove_dir_all(&dir_path);
            1
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            let _ = fs::remove_dir_all(&dir_path);
            1
        }
    }
}

