fn execute_java_file(path: &Path) -> i32 {
    let class_name = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("Main")
        .to_string();

    let dir_path = std::env::temp_dir().join(format!("run-java{}", rand_suffix()));
    let _ = fs::create_dir_all(&dir_path);

    // Copy the file to temp dir
    let src_file = dir_path.join(format!("{}.java", class_name));
    if let Err(_) = fs::copy(path, &src_file) {
        // Try to compile in place
        let compile_result = Command::new("javac")
            .arg(path)
            .status();

        match compile_result {
            Ok(status) if status.success() => {
                let run_result = Command::new("java")
                    .arg("-cp")
                    .arg(path.parent().unwrap_or(Path::new(".")))
                    .arg(&class_name)
                    .status();
                return match run_result {
                    Ok(s) => s.code().unwrap_or(1),
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        1
                    }
                };
            }
            Ok(_) => return 1,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
                return 1;
            }
            Err(e) => {
                eprintln!("Error: {}", e);
                return 1;
            }
        }
    }

    let compile_result = Command::new("javac")
        .arg(&src_file)
        .current_dir(&dir_path)
        .status();

    match compile_result {
        Ok(status) if status.success() => {
            let run_result = Command::new("java")
                .arg(&class_name)
                .current_dir(&dir_path)
                .status();
            let code = match run_result {
                Ok(s) => s.code().unwrap_or(1),
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            };
            let _ = fs::remove_dir_all(&dir_path);
            code
        }
        Ok(_) => {
            let _ = fs::remove_dir_all(&dir_path);
            1
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
            let _ = fs::remove_dir_all(&dir_path);
            1
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            let _ = fs::remove_dir_all(&dir_path);
            1
        }
    }
}

fn extract_java_class_name(code: &str) -> Option<String> {
    for line in code.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("public class ") {
            let rest = &trimmed["public class ".len()..];
            let class_name = rest
                .split(|c: char| !c.is_alphanumeric() && c != '_')
                .next()?
                .to_string();
            if !class_name.is_empty() {
                return Some(class_name);
            }
        }
    }
    None
}

