use std::fs;
use std::io::{self, BufRead, Write};
use std::path::PathBuf;
use std::process::Command;
use std::time::Instant;
use tempfile::TempDir;

use crate::language::Language;
use crate::detect::detect_language;

pub fn run_repl(initial_lang: Option<Language>) {
    let mut current_lang = initial_lang.unwrap_or(Language::Python);
    let mut auto_detect = true;
    let mut session = ReplSession::new(&current_lang);

    println!("run universal REPL. Type :help for commands.");

    let stdin = io::stdin();

    loop {
        // Print prompt
        print!("{}>>> ", current_lang.name());
        let _ = io::stdout().flush();

        // Read line
        let mut line = String::new();
        match stdin.lock().read_line(&mut line) {
            Ok(0) => break, // EOF
            Ok(_) => {},
            Err(_) => break,
        }

        let input = line.trim_end_matches('\n').trim_end_matches('\r').to_string();

        if input.is_empty() {
            continue;
        }

        // Handle commands
        if input.starts_with(':') {
            let cmd_part = &input[1..];
            let parts: Vec<&str> = cmd_part.splitn(2, ' ').collect();
            let cmd = parts[0];
            let arg = parts.get(1).copied().unwrap_or("").trim();

            match cmd.to_lowercase().as_str() {
                "help" => {
                    println!("Commands:");
                    println!("  :help                 Show this help message");
                    println!("  :languages            List available languages");
                    println!("  :lang <id>            Switch to language <id>");
                    println!("  :detect on|off        Enable or disable auto language detection");
                    println!("  :reset                Reset the current language session");
                    println!("  :load <path>          Execute a file in the current language");
                    println!("  :exit, :quit          Leave the REPL");
                    println!("Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.");
                }
                "languages" => {
                    println!("available languages: {}", crate::language::available_languages_str());
                }
                "lang" => {
                    if arg.is_empty() {
                        println!("Usage: :lang <id>");
                    } else {
                        match switch_language(arg) {
                            Ok(lang) => {
                                current_lang = lang;
                                session = ReplSession::new(&current_lang);
                                println!("switched to {}", current_lang.name());
                            }
                            Err(_) => {
                                eprintln!("Error: language '{}' not supported. Available: {}", 
                                    arg.to_lowercase(), 
                                    crate::language::available_languages_str());
                                return;
                            }
                        }
                    }
                }
                "detect" => {
                    match arg {
                        "on" => {
                            auto_detect = true;
                            println!("auto-detect enabled");
                        }
                        "off" => {
                            auto_detect = false;
                            println!("auto-detect disabled");
                        }
                        _ => {
                            println!("Usage: :detect on|off");
                        }
                    }
                }
                "reset" => {
                    session = ReplSession::new(&current_lang);
                    println!("session for '{}' reset", current_lang.name());
                }
                "load" => {
                    if arg.is_empty() {
                        println!("Usage: :load <path>");
                    } else {
                        let _ = crate::executor::execute_file(&current_lang, &std::path::Path::new(arg));
                    }
                }
                "exit" | "quit" => {
                    break;
                }
                _ => {
                    // Check if it's a language shortcut
                    match switch_language(cmd) {
                        Ok(lang) => {
                            current_lang = lang;
                            session = ReplSession::new(&current_lang);
                            println!("switched to {}", current_lang.name());
                        }
                        Err(_) => {
                            println!("unknown command: :{}. Type :help for help.", cmd);
                        }
                    }
                }
            }
            continue;
        }

        // Auto-detect language
        if auto_detect {
            let detected = detect_language(&input);
            if detected != current_lang {
                println!("[auto-detect] switching {} → {}", current_lang.name(), detected.name());
                current_lang = detected;
                session = ReplSession::new(&current_lang);
            }
        }

        // Execute the input
        session.execute(&input, &current_lang);
    }
}

fn switch_language(name: &str) -> Result<Language, ()> {
    crate::language::resolve_lang(name).ok_or(())
}

/// Manages the cumulative session state for a language REPL
struct ReplSession {
    statements: Vec<String>,
    top_level_items: Vec<String>,  // For Rust: function definitions
    session_dir: Option<TempDir>,
}

impl ReplSession {
    fn new(lang: &Language) -> Self {
        let dir = match lang {
            Language::Python | Language::Perl | Language::Bash 
            | Language::Ruby | Language::Lua | Language::Php
            | Language::R | Language::Julia => {
                // Create a persistent temp dir for the session file
                let dir_name = format!("run-{}-repl", lang.name());
                let path = std::env::temp_dir().join(format!("{}{}", dir_name, crate::executor::rand_suffix_pub()));
                let _ = fs::create_dir_all(&path);

                // Create a dummy TempDir that we'll manage manually
                None
            }
            _ => None,
        };

        ReplSession {
            statements: Vec::new(),
            top_level_items: Vec::new(),
            session_dir: dir,
        }
    }

    fn execute(&mut self, input: &str, lang: &Language) {
        match lang {
            Language::Python => self.execute_python(input),
            Language::Perl => self.execute_perl(input),
            Language::Bash => self.execute_bash(input),
            Language::Go => self.execute_go(input),
            Language::Rust => self.execute_rust(input),
            Language::C => self.execute_c(input),
            Language::Cpp => self.execute_cpp(input),
            _ => {
                // For other languages, just run inline
                let _ = crate::executor::execute_code(lang, input, &[]);
            }
        }
    }

    fn session_dir_path(&mut self, lang_name: &str) -> PathBuf {
        let dir_name = format!("run-{}-repl", lang_name);
        let path = std::env::temp_dir().join(format!("{}{}", dir_name, crate::executor::rand_suffix_pub()));
        let _ = fs::create_dir_all(&path);
        path
    }

    fn execute_python(&mut self, input: &str) {
        // Use a persistent session file
        let session_path = get_or_create_session_path("python", &mut self.session_dir);

        // Python session template (3 lines before user code):
        let header = "import sys\nimport os\n\n";

        // Build full session content
        let mut content = header.to_string();
        for stmt in &self.statements {
            content.push_str(stmt);
            content.push('\n');
        }
        content.push_str(input);
        content.push('\n');

        // Write and run
        let session_file = session_path.join("session.py");
        let _ = fs::write(&session_file, &content);

        let result = Command::new("python3")
            .arg(&session_file)
            .status();

        match result {
            Ok(status) if status.success() => {
                self.statements.push(input.to_string());
            }
            Ok(_) => {
                // Error - don't add to session
            }
            Err(e) => {
                eprintln!("Error: {}", e);
            }
        }
    }

    fn execute_perl(&mut self, input: &str) {
        let session_path = get_or_create_session_path("perl", &mut self.session_dir);

        // Build session file content
        let header = "use strict;\nuse warnings;\nuse Data::Dumper;\n\n";
        let mut content = header.to_string();
        for stmt in &self.statements {
            content.push_str(stmt);
            if !stmt.ends_with(';') {
                content.push(';');
            }
            content.push('\n');
        }
        content.push_str(input);
        if !input.ends_with(';') {
            content.push(';');
        }
        content.push('\n');

        let session_file = session_path.join("session.pl");
        let _ = fs::write(&session_file, &content);

        let result = Command::new("perl")
            .arg(&session_file)
            .status();

        match result {
            Ok(status) if status.success() => {
                self.statements.push(input.to_string());
            }
            Ok(_) => {}
            Err(e) => {
                eprintln!("Error: {}", e);
            }
        }
    }

    fn execute_bash(&mut self, input: &str) {
        let session_path = get_or_create_session_path("bash", &mut self.session_dir);

        // Build session file
        let header = "#!/bin/bash\n\n";
        let mut content = header.to_string();
        for stmt in &self.statements {
            content.push_str(stmt);
            content.push('\n');
        }
        content.push_str(input);
        content.push('\n');

        let session_file = session_path.join("session.sh");
        let _ = fs::write(&session_file, &content);

        let result = Command::new("bash")
            .arg(&session_file)
            .status();

        match result {
            Ok(status) if status.success() => {
                self.statements.push(input.to_string());
            }
            Ok(_) => {}
            Err(e) => {
                eprintln!("Error: {}", e);
            }
        }
    }

    fn execute_go(&mut self, input: &str) {
        let session_path = get_or_create_session_path_raw("go", &mut self.session_dir);

        // Build Go session file
        let mut content = String::from("package main\n\nimport \"fmt\"\n\n");
        content.push_str("func main() {\n");
        for stmt in &self.statements {
            content.push_str("    ");
            content.push_str(stmt);
            content.push('\n');
        }
        content.push_str("    ");
        content.push_str(input);
        content.push('\n');
        content.push_str("}\n");

        let session_file = session_path.join("main.go");
        let _ = fs::write(&session_file, &content);

        let start = Instant::now();
        let result = Command::new("/usr/local/go/bin/go")
            .arg("run")
            .arg("main.go")
            .current_dir(&session_path)
            .status();
        let elapsed = start.elapsed().as_millis();

        match result {
            Ok(status) if status.success() => {
                self.statements.push(input.to_string());
            }
            Ok(status) => {
                eprintln!("[exit code {}] ({}ms)", status.code().unwrap_or(1), elapsed);
            }
            Err(e) => {
                eprintln!("Error: {}", e);
            }
        }
    }

    fn execute_rust(&mut self, input: &str) {
        // Determine if input is a function definition or an expression
        let is_fn_def = input.trim_start().starts_with("fn ") || 
                        input.trim_start().starts_with("struct ") ||
                        input.trim_start().starts_with("enum ") ||
                        input.trim_start().starts_with("impl ") ||
                        input.trim_start().starts_with("type ") ||
                        input.trim_start().starts_with("const ") ||
                        input.trim_start().starts_with("static ") ||
                        input.trim_start().starts_with("use ") ||
                        input.trim_start().starts_with("mod ");

        let session_path = get_or_create_session_path_raw("rust", &mut self.session_dir);

        // Build Rust session file
        let mut content = String::from("use std::fmt::Debug;\n\nfn __print<T: Debug>(value: T) {\n    println!(\"{:?}\", value);\n}\n\n");

        // Add function definitions
        for item in &self.top_level_items {
            content.push_str(item);
            content.push('\n');
            content.push('\n');
        }

        content.push_str("fn main() {\n");
        // Previous successful expressions
        for stmt in &self.statements {
            content.push_str("    __print(");
            content.push_str(stmt);
            content.push_str(");\n");
        }

        if is_fn_def {
            // For function definitions, don't wrap in __print
            // Add to top_level_items and exit main early
            content.push_str("}\n");
        } else {
            content.push_str("    __print(");
            content.push_str(input);
            content.push_str(");\n");
            content.push_str("}\n");
        }

        // Also add function defs at top level if needed
        if is_fn_def {
            // Rebuild content with the new function def
            let mut new_content = String::from("use std::fmt::Debug;\n\nfn __print<T: Debug>(value: T) {\n    println!(\"{:?}\", value);\n}\n\n");
            for item in &self.top_level_items {
                new_content.push_str(item);
                new_content.push('\n');
                new_content.push('\n');
            }
            new_content.push_str(input);
            new_content.push('\n');
            new_content.push('\n');
            new_content.push_str("fn main() {\n");
            for stmt in &self.statements {
                new_content.push_str("    __print(");
                new_content.push_str(stmt);
                new_content.push_str(");\n");
            }
            new_content.push_str("}\n");
            content = new_content;
        }

        let session_file = session_path.join("session.rs");
        let _ = fs::write(&session_file, &content);

        let bin_file = session_path.join("session");

        let start = Instant::now();
        let compile_result = Command::new("rustc")
            .arg("--edition")
            .arg("2021")
            .arg("-o")
            .arg(&bin_file)
            .arg(&session_file)
            .status();

        match compile_result {
            Ok(status) if status.success() => {
                let run_result = Command::new(&bin_file).status();
                match run_result {
                    Ok(run_status) if run_status.success() => {
                        if is_fn_def {
                            self.top_level_items.push(input.to_string());
                        } else {
                            self.statements.push(input.to_string());
                        }
                    }
                    Ok(run_status) => {
                        let elapsed = start.elapsed().as_millis();
                        eprintln!("[exit code {}] ({}ms)", run_status.code().unwrap_or(1), elapsed);
                    }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                    }
                }
            }
            Ok(status) => {
                let elapsed = start.elapsed().as_millis();
                eprintln!("[exit code {}] ({}ms)", status.code().unwrap_or(1), elapsed);
            }
            Err(e) => {
                eprintln!("Error: {}", e);
            }
        }
    }

    fn execute_c(&mut self, input: &str) {
        let session_path = get_or_create_session_path_raw("c", &mut self.session_dir);

        // Build C session file with cumulative state
        let mut content = String::from(
            "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\
