        match lang {
            Language::Python => self.execute_python(input),
            Language::Perl => self.execute_perl(input),
            Language::Bash => self.execute_bash(input),
            Language::Go => self.execute_go(input),
            Language::Rust => self.execute_rust(input),
            Language::C => self.execute_c(input),
            Language::Cpp => self.execute_cpp(input),
