fn get_or_create_session_path(lang: &str, dir: &mut Option<TempDir>) -> PathBuf {
    let dir_name = format!("run-{}-repl{}", lang, crate::executor::rand_suffix_pub());
    let path = std::env::temp_dir().join(&dir_name);
    let _ = fs::create_dir_all(&path);
    path
}

fn get_or_create_session_path_raw(lang: &str, dir: &mut Option<TempDir>) -> PathBuf {
    let dir_name = format!("run-{}-repl{}", lang, crate::executor::rand_suffix_pub());
    let path = std::env::temp_dir().join(&dir_name);
    let _ = fs::create_dir_all(&path);
    path
}
