    if args.help {
        print_help();
        return;
    }

    let lang_str = args.lang.as_deref().map(|s| s.to_lowercase());

    // Validate language if provided
    if let Some(ref ls) = lang_str {
        if language::resolve_lang(ls).is_none() {
            eprintln!(
                "Error: Unknown language '{}'. Available languages: {}",
                ls,
                language::available_languages_str()
            );
            process::exit(1);
        }
    }

    if let Some(code) = args.code {
        // Execute inline code
        let trimmed = code.trim();
        if trimmed.is_empty() {
            eprintln!("Error: Inline code provided via --code must not be empty");
            process::exit(1);
        }

        let lang = if let Some(ref ls) = lang_str {
            language::resolve_lang(ls).unwrap()
        } else if args.no_detect {
            language::Language::Python
        } else {
            detect::detect_language(&code)
        };

        let exit_code = executor::execute_code(&lang, &code);
        process::exit(exit_code);
    } else if let Some(file_path) = args.file {
        let lang = if let Some(ref ls) = lang_str {
            language::resolve_lang(ls).unwrap()
        } else {
            detect::detect_language_from_file(Path::new(&file_path))
        };

        let exit_code = executor::execute_file(&lang, Path::new(&file_path));
        process::exit(exit_code);
    } else if !args.positional.is_empty() {
        let first = args.positional[0].to_lowercase();
        if let Some(lang) = language::resolve_lang(&first) {
            if args.positional.len() == 1 {
                // Just the language - start REPL
                repl::run_repl(Some(lang));
            } else {
                // Language + code
                let code = args.positional[1..].join(" ");
                let exit_code = executor::execute_code(&lang, &code);
                process::exit(exit_code);
            }
        } else {
            // Treat as file path
            let file_path = PathBuf::from(&args.positional[0]);
            let lang = if let Some(ref ls) = lang_str {
                language::resolve_lang(ls).unwrap()
            } else {
                detect::detect_language_from_file(&file_path)
            };

            let exit_code = executor::execute_file(&lang, &file_path);
            process::exit(exit_code);
        }
    } else {
        // Check stdin/REPL mode
        if is_stdin_tty() {
            let lang = lang_str.as_deref().and_then(|l| language::resolve_lang(l));
            repl::run_repl(lang);
        } else {
            let mut code = String::new();
            std::io::stdin().read_to_string(&mut code).unwrap_or(0);

            if code.is_empty() {
                return;
            }

            let lang = if let Some(ref ls) = lang_str {
                language::resolve_lang(ls).unwrap()
            } else if args.no_detect {
                language::Language::Python
            } else {
                detect::detect_language(&code)
            };

            let exit_code = executor::execute_stdin(&lang, &code);
            process::exit(exit_code);
        }
