    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("fn main(") {
            return Language::Rust;
        }
        if t.starts_with("use std::") {
            return Language::Rust;
        }
    }

    // Priority 4: C/C++ - "#include" at line start -> C++
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("#include") {
            return Language::Cpp;
        }
    }

    // Priority 5: JavaScript - "function ", "console.log", "module " at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("function ") || t.starts_with("function(") {
            return Language::JavaScript;
        }
        if t.starts_with("console.log") {
            return Language::JavaScript;
        }
        if t.starts_with("module ") || t.starts_with("module.") {
            return Language::JavaScript;
        }
    }

    // Priority 6: R - "<-" operator anywhere, or "cat(" at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.contains("<-") {
            return Language::R;
        }
        if t.starts_with("cat(") {
            return Language::R;
        }
    }

    // Priority 7: Julia - "println(" or "using " at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("println(") {
            return Language::Julia;
        }
        if t.starts_with("using ") {
            return Language::Julia;
        }
    }

    // Priority 8: Kotlin - "fun main(" or "val <id> =" (no colon before =) at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("fun main(") {
            return Language::Kotlin;
        }
        if t.starts_with("val ") {
            let rest = &t[4..];
            // Skip identifier characters
            let after_id = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
            if after_id.starts_with(" = ") || after_id.starts_with('=') {
                if !after_id.is_empty() {
                    return Language::Kotlin;
                }
            }
        }
    }

    // Priority 9: Haskell - "main ::" or "let " or "::" at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("main ::") || t.starts_with("main::") {
            return Language::Haskell;
        }
        if t.starts_with("let ") || t.starts_with("let\t") {
            return Language::Haskell;
        }
        if t.starts_with("putStrLn ") || t.starts_with("putStrLn(") {
            return Language::Haskell;
        }
        if t.contains(" :: ") {
            return Language::Haskell;
        }
        // "main = ..." Haskell-style
        if t.starts_with("main = ") {
            return Language::Haskell;
        }
    }

