    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("IO.") {
            return Language::Elixir;
        }
        if t.starts_with("defmodule ") {
            return Language::Elixir;
        }
    }

    // Priority 11: Groovy - "package " (not "package main...") at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("package ") && !t.starts_with("package main") {
            return Language::Groovy;
        }
    }

    // Priority 12: Perl - "use strict", "use warnings", or "print \"...\";" at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("use strict") || t.starts_with("use warnings") {
            return Language::Perl;
        }
        if t.starts_with("print ") && t.trim_end().ends_with(';') {
            if let Some(c) = t[6..].chars().next() {
                if c == '"' || c == '\'' {
                    return Language::Perl;
                }
            }
        }
    }

    // Priority 13: Ruby - "puts " at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("puts ") || t.starts_with("puts(") {
            return Language::Ruby;
        }
    }

    // Priority 14: PHP - "<?php" or "echo " with quote at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("<?php") {
            return Language::Php;
        }
        if t.starts_with("echo ") {
            if let Some(c) = t[5..].chars().next() {
                if c == '"' || c == '\'' {
                    return Language::Php;
                }
            }
        }
    }

    // Priority 15: Lua - "print(" at line start (not "printfoo(")
    for line in code.lines() {
        let t = line.trim_start();
        if let Some(rest) = t.strip_prefix("print") {
            if rest.starts_with('(') {
                return Language::Lua;
            }
        }
    }

    // Priority 16: Nim - "var x: Type" at line start
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("var ") {
            let rest = &t[4..];
            let after_id = rest.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_');
            let trimmed = after_id.trim_start();
            if trimmed.starts_with(':') {
                return Language::Nim;
            }
        }
        if t.starts_with("proc ") {
            return Language::Nim;
        }
    }

    // Priority 17: Bash - shebang, "echo " without quote, "print " without paren/semicolon
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("#!/") {
            return Language::Bash;
        }
        if t.starts_with("echo ") {
            if let Some(c) = t[5..].chars().next() {
                if c != '"' && c != '\'' {
                    return Language::Bash;
                }
            }
        }
        // "print word" without semicolon at end (bash print)
        if t.starts_with("print ") && !t.trim_end().ends_with(';') {
            if let Some(c) = t[6..].chars().next() {
                if c != '(' {
                    return Language::Bash;
                }
            }
        }
    }

    // Default: Python
    Language::Python
}

pub fn detect_language_from_file(path: &Path) -> Language {
    if let Some(ext) = path.extension() {
        if let Some(ext_str) = ext.to_str() {
            if let Some(lang) = language_from_extension(ext_str) {
                return lang;
            }
        }
    }
    Language::Python
}
