fn run_stdin(cmd: &str, args: &[&str], code: &str) -> i32 {
    let mut child = match Command::new(cmd).args(args).stdin(Stdio::piped()).spawn() {
        Ok(c) => c,
        Err(e) => { eprintln!("Error: {}", e); return 1; }
    };
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(code.as_bytes());
    }
    child.wait().map(|s| s.code().unwrap_or(1)).unwrap_or(1)
}

fn run_stdin_result(cmd: &str, args: &[&str], code: &str) -> std::io::Result<i32> {
    let mut child = Command::new(cmd).args(args).stdin(Stdio::piped()).spawn()?;
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(code.as_bytes());
    }
    Ok(child.wait()?.code().unwrap_or(1))
}

fn execute_rust_code(code: &str) -> i32 {
    let dir = std::env::temp_dir().join(format!("run-rust{}", rand_suffix()));
    let _ = fs::create_dir_all(&dir);
    let src = dir.join("main.rs");
    let bin = dir.join("main");
    let _ = fs::write(&src, code);

    let compile = Command::new("rustc")
        .arg("--edition").arg("2021")
        .arg("--crate-name").arg("run_snippet")
        .arg("-o").arg(&bin)
        .arg(&src)
        .status();

    let result = match compile {
        Ok(s) if s.success() => {
            Command::new(&bin).status()
                .map(|s| s.code().unwrap_or(1))
                .unwrap_or(1)
        }
        Ok(_) => 1,
        Err(e) => { eprintln!("Error: {}", e); 1 }
    };
    let _ = fs::remove_dir_all(&dir);
    result
}

fn execute_go_code(code: &str) -> i32 {
