    let _ = fs::create_dir_all(&dir);
    let src = dir.join("main.go");
    let _ = fs::write(&src, code);

    let result = Command::new("/usr/local/go/bin/go")
        .arg("run").arg("main.go")
        .current_dir(&dir)
        .status();

    let code = match result {
        Ok(s) => s.code().unwrap_or(1),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    No such file or directory (os error 2)", src.display());
            1
        }
        Err(e) => { eprintln!("Error: {}", e); 1 }
    };
    let _ = fs::remove_dir_all(&dir);
    code
}

