    let mut result = String::new();
    let mut seed = (nanos as u64).wrapping_mul(6364136223846793005)
        ^ ((pid as u64).wrapping_mul(1442695040888963407));
    for _ in 0..6 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        result.push(chars[((seed >> 33) as usize) % chars.len()] as char);
    }
    result
}

fn needs_c_wrap(code: &str) -> bool {
    !code.contains("main(") && !code.contains("#include")
}

