fn execute_c_code(code: &str) -> i32 {
    let dir = std::env::temp_dir().join(format!("run-c{}", rand_suffix()));
    let _ = fs::create_dir_all(&dir);
    let src = dir.join("main.c");
    let bin = dir.join("main");

    let final_code = if needs_c_wrap(code) {
        let indented = code.lines().collect::<Vec<_>>().join("\n    ");
        format!("#include <stdio.h>\n\nint main() {{\n    {}\n    return 0;\n}}\n", indented)
    } else {
        code.to_string()
    };

    let _ = fs::write(&src, &final_code);

    let compile = Command::new("gcc").arg("-o").arg(&bin).arg(&src).status();
    let result = match compile {
        Ok(s) if s.success() => Command::new(&bin).status().map(|s| s.code().unwrap_or(1)).unwrap_or(1),
        Ok(_) => 1,
        Err(e) => { eprintln!("Error: {}", e); 1 }
    };
    let _ = fs::remove_dir_all(&dir);
    result
}

