fn execute_java_file(path: &Path) -> i32 {
    let class_name = path.file_stem().and_then(|s| s.to_str()).unwrap_or("Main").to_string();
    let dir = std::env::temp_dir().join(format!("run-java{}", rand_suffix()));
    let _ = fs::create_dir_all(&dir);

    let src = dir.join(format!("{}.java", class_name));
    if fs::copy(path, &src).is_ok() {
        let compile = Command::new("javac").arg(&src).current_dir(&dir).status();
        let result = match compile {
            Ok(s) if s.success() => {
                Command::new("java").arg(&class_name).current_dir(&dir).status()
                    .map(|s| s.code().unwrap_or(1)).unwrap_or(1)
            }
            Ok(_) => 1,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
                1
            }
            Err(e) => { eprintln!("Error: {}", e); 1 }
        };
        let _ = fs::remove_dir_all(&dir);
        result
    } else {
        let _ = fs::remove_dir_all(&dir);
        let compile = Command::new("javac").arg(path).status();
        match compile {
            Ok(s) if s.success() => {
                Command::new("java").arg("-cp").arg(path.parent().unwrap_or(Path::new("."))).arg(&class_name).status()
                    .map(|s| s.code().unwrap_or(1)).unwrap_or(1)
            }
            Ok(_) => 1,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
                1
            }
            Err(e) => { eprintln!("Error: {}", e); 1 }
        }
    }
}

fn extract_java_class_name(code: &str) -> Option<String> {
    for line in code.lines() {
        let t = line.trim();
        if t.starts_with("public class ") {
            let rest = &t["public class ".len()..];
            let name: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
            if !name.is_empty() { return Some(name); }
        }
    }
    None
}

