struct ReplSession {
    statements: Vec<String>,
    top_level: Vec<String>,
    session_dir: PathBuf,
}

impl ReplSession {
    fn new(lang: &Language) -> Self {
        let dir_name = format!("run-{}-repl{}", lang.name(), rand_suffix());
        let session_dir = std::env::temp_dir().join(dir_name);
        let _ = fs::create_dir_all(&session_dir);
        ReplSession {
            statements: Vec::new(),
            top_level: Vec::new(),
            session_dir,
        }
    }

    fn execute(&mut self, input: &str, lang: &Language) {
        match lang {
            Language::Python => self.exec_python(input),
            Language::Perl => self.exec_perl(input),
            Language::Bash => self.exec_bash(input),
            Language::Go => self.exec_go(input),
            Language::Rust => self.exec_rust(input),
            Language::C => self.exec_c(input),
            Language::Cpp => self.exec_cpp(input),
            _ => {
                let _ = crate::executor::execute_code(lang, input);
            }
        }
    }

    fn exec_python(&mut self, input: &str) {
        let session_file = self.session_dir.join("session.py");
        let mut content = String::from("import sys\nimport os\n\n");
        for s in &self.statements {
            content.push_str(s);
            content.push('\n');
        }
        content.push_str(input);
        content.push('\n');
        let _ = fs::write(&session_file, &content);

        match Command::new("python3").arg(&session_file).status() {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            _ => {}
        }
    }

    fn exec_perl(&mut self, input: &str) {
        let session_file = self.session_dir.join("session.pl");
        let mut content = String::from("use strict;\nuse warnings;\nuse Data::Dumper;\n\n");
        for s in &self.statements {
            content.push_str(s);
            if !s.trim_end().ends_with(';') { content.push(';'); }
            content.push('\n');
        }
        let stmt = if input.trim_end().ends_with(';') {
            input.to_string()
        } else {
            format!("{};", input)
        };
        content.push_str(&stmt);
        content.push('\n');
        let _ = fs::write(&session_file, &content);

        match Command::new("perl").arg(&session_file).status() {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            _ => {}
        }
    }

    fn exec_bash(&mut self, input: &str) {
        let session_file = self.session_dir.join("session.sh");
        let mut content = String::from("#!/bin/bash\n\n");
        for s in &self.statements {
            content.push_str(s);
            content.push('\n');
        }
        content.push_str(input);
        content.push('\n');
        let _ = fs::write(&session_file, &content);

        match Command::new("bash").arg(&session_file).status() {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            _ => {}
        }
    }

    fn exec_go(&mut self, input: &str) {
        let mut content = String::from("package main\n\nimport \"fmt\"\n\nfunc main() {\n");
        for s in &self.statements {
            content.push_str("    "); content.push_str(s); content.push('\n');
        }
        content.push_str("    "); content.push_str(input); content.push('\n');
        content.push_str("}\n");

        let session_file = self.session_dir.join("main.go");
        let _ = fs::write(&session_file, &content);

        let start = Instant::now();
        match Command::new("/usr/local/go/bin/go")
            .arg("run").arg("main.go")
            .current_dir(&self.session_dir)
            .status()
        {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            Ok(s) => {
                let ms = start.elapsed().as_millis();
                eprintln!("[exit code {}] ({}ms)", s.code().unwrap_or(1), ms);
            }
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    fn exec_rust(&mut self, input: &str) {
        let is_top = input.trim_start().starts_with("fn ")
            || input.trim_start().starts_with("struct ")
            || input.trim_start().starts_with("enum ")
            || input.trim_start().starts_with("impl ")
            || input.trim_start().starts_with("type ")
            || input.trim_start().starts_with("const ")
            || input.trim_start().starts_with("static ")
            || input.trim_start().starts_with("use ")
            || input.trim_start().starts_with("mod ");

        let mut content = String::from(
            "use std::fmt::Debug;\n\nfn __print<T: Debug>(value: T) {\n    println!(\"{:?}\", value);\n}\n\n"
        );

        for item in &self.top_level {
            content.push_str(item); content.push('\n'); content.push('\n');
        }

        if is_top {
            content.push_str(input); content.push('\n'); content.push('\n');
        }

        content.push_str("fn main() {\n");
        for s in &self.statements {
            content.push_str("    __print("); content.push_str(s); content.push_str(");\n");
        }
        if !is_top {
            content.push_str("    __print("); content.push_str(input); content.push_str(");\n");
        }
        content.push_str("}\n");

        let session_file = self.session_dir.join("session.rs");
        let bin = self.session_dir.join("session_bin");
        let _ = fs::write(&session_file, &content);

        let start = Instant::now();
        match Command::new("rustc")
            .arg("--edition").arg("2021")
            .arg("-o").arg(&bin)
            .arg(&session_file)
            .status()
        {
            Ok(s) if s.success() => {
                let ms = start.elapsed().as_millis();
                match Command::new(&bin).status() {
                    Ok(rs) if rs.success() => {
                        if is_top { self.top_level.push(input.to_string()); }
                        else { self.statements.push(input.to_string()); }
                    }
                    Ok(rs) => {
                        eprintln!("[exit code {}] ({}ms)", rs.code().unwrap_or(1), ms);
                    }
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Ok(s) => {
                let ms = start.elapsed().as_millis();
                eprintln!("[exit code {}] ({}ms)", s.code().unwrap_or(1), ms);
            }
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    fn exec_c(&mut self, input: &str) {
        let mut content = String::from(
            "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\
             static void __print_int(long long value) { printf(\"%lld\\n\", value); }\n\
             static void __print_uint(unsigned long long value) { printf(\"%llu\\n\", value); }\n\
             static void __print_double(double value) { printf(\"%0.17g\\n\", value); }\n\
             static void __print_cstr(const char *value) { if (!value) { printf(\"(null)\\n\"); } else { printf(\"%s\\n\", value); } }\n\
             static void __print_char(int value) { printf(\"%d\\n\", value); }\n\
             static void __print_pointer(const void *value) { printf(\"%p\\n\", value); }\n"
        );

        for item in &self.top_level {
            content.push_str(item); content.push('\n');
        }

        content.push_str("\nint main(void) {\n");
        for s in &self.statements {
            content.push_str("    "); content.push_str(s);
            if !s.trim_end().ends_with(';') { content.push(';'); }
            content.push('\n');
        }
        content.push_str("    "); content.push_str(input);
        if !input.trim_end().ends_with(';') { content.push(';'); }
        content.push('\n');
        content.push_str("    return 0;\n}\n");

        let session_file = self.session_dir.join("main.c");
        let bin = self.session_dir.join("main_bin");
        let _ = fs::write(&session_file, &content);

        let start = Instant::now();
        match Command::new("gcc").arg("-o").arg(&bin).arg(&session_file).status() {
            Ok(s) if s.success() => {
                let ms = start.elapsed().as_millis();
                match Command::new(&bin).status() {
                    Ok(rs) if rs.success() => { self.statements.push(input.to_string()); }
                    Ok(rs) => eprintln!("[exit code {}] ({}ms)", rs.code().unwrap_or(1), ms),
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Ok(s) => {
                let ms = start.elapsed().as_millis();
                eprintln!("[exit code {}] ({}ms)", s.code().unwrap_or(1), ms);
            }
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    fn exec_cpp(&mut self, input: &str) {
        let mut content = String::from(
            "#include <iostream>\n#include <string>\n#include <vector>\n\
             #include <map>\n#include <algorithm>\n#include <functional>\n\
             #include <memory>\n#include <stdexcept>\n#include <sstream>\n\n"
        );

        for item in &self.top_level {
            content.push_str(item); content.push('\n');
        }

        content.push_str("\nint main() {\n");
        for s in &self.statements {
            content.push_str("    std::cout << ("); content.push_str(s);
            content.push_str(") << std::endl;\n");
        }
        content.push_str("    std::cout << ("); content.push_str(input);
        content.push_str(") << std::endl;\n");
        content.push_str("    return 0;\n}\n");

        let session_file = self.session_dir.join("main.cpp");
        let bin = self.session_dir.join("main_bin");
        let _ = fs::write(&session_file, &content);

        let start = Instant::now();
        match Command::new("g++").arg("-std=c++17").arg("-o").arg(&bin).arg(&session_file).status() {
            Ok(s) if s.success() => {
                let ms = start.elapsed().as_millis();
                match Command::new(&bin).status() {
                    Ok(rs) if rs.success() => { self.statements.push(input.to_string()); }
                    Ok(rs) => eprintln!("[exit code {}] ({}ms)", rs.code().unwrap_or(1), ms),
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Ok(s) => {
                let ms = start.elapsed().as_millis();
                eprintln!("[exit code {}] ({}ms)", s.code().unwrap_or(1), ms);
            }
            Err(e) => eprintln!("Error: {}", e),
        }
    }
