}

fn parse_args() -> Result<Args, String> {
    let all_args: Vec<String> = std::env::args().collect();
    let args = &all_args[1..];
    let mut result = Args {
        version: false,
        help: false,
        lang: None,
        file: None,
        code: None,
        no_detect: false,
        positional: Vec::new(),
    };

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-V" | "--version" => result.version = true,
            "-h" | "--help" => result.help = true,
            "--no-detect" => result.no_detect = true,
            "-l" | "--lang" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: a value is required for '--lang <LANG>' but none was supplied\n\nFor more information, try '--help'."));
                }
                result.lang = Some(args[i].clone());
            }
            "-f" | "--file" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: a value is required for '--file <PATH>' but none was supplied\n\nFor more information, try '--help'."));
                }
                result.file = Some(args[i].clone());
            }
            "-c" | "--code" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: a value is required for '--code <CODE>' but none was supplied\n\nFor more information, try '--help'."));
                }
                result.code = Some(args[i].clone());
            }
            s if s.starts_with("--lang=") => {
                result.lang = Some(s[7..].to_string());
            }
            s if s.starts_with("--file=") => {
                result.file = Some(s[7..].to_string());
            }
            s if s.starts_with("--code=") => {
                result.code = Some(s[7..].to_string());
            }
            _ => {
                result.positional.push(args[i].clone());
            }
        }
        i += 1;
    }

    Ok(result)
}

fn get_prog_name() -> String {
    std::env::args().next()
        .and_then(|p| std::path::Path::new(&p).file_name()
            .and_then(|n| n.to_str())
            .map(|s| s.to_string()))
        .unwrap_or_else(|| "run".to_string())
}

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(2);
        }
    };

    if args.version {
        print_version();
        return;
    }

    if args.help {
        print_help(&get_prog_name());
        return;
    }

    let lang_str = args.lang.as_deref().map(|s| s.to_lowercase());

    // Validate language if provided
    if let Some(ref ls) = lang_str {
        if language::resolve_lang(ls).is_none() {
            eprintln!(
                "Error: Unknown language '{}'. Available languages: {}",
                ls,
                language::available_languages_str()
            );
            process::exit(1);
        }
    }

    if let Some(code) = args.code {
        let trimmed = code.trim();
        if trimmed.is_empty() {
            eprintln!("Error: Inline code provided via --code must not be empty");
            process::exit(1);
        }

        let lang = if let Some(ref ls) = lang_str {
            language::resolve_lang(ls).unwrap()
        } else if args.no_detect {
            language::Language::Python
        } else {
            detect::detect_language(&code)
        };

        let exit_code = executor::execute_code(&lang, &code);
        process::exit(exit_code);
    } else if let Some(file_path) = args.file {
        let lang = if let Some(ref ls) = lang_str {
            language::resolve_lang(ls).unwrap()
        } else {
            detect::detect_language_from_file(Path::new(&file_path))
        };

        let exit_code = executor::execute_file(&lang, Path::new(&file_path));
        process::exit(exit_code);
    } else if !args.positional.is_empty() {
        let first = args.positional[0].to_lowercase();
        if let Some(lang) = language::resolve_lang(&first) {
            if args.positional.len() == 1 {
                repl::run_repl(Some(lang));
            } else {
                let code = args.positional[1..].join(" ");
                let exit_code = executor::execute_code(&lang, &code);
                process::exit(exit_code);
            }
        } else {
            let file_path = PathBuf::from(&args.positional[0]);
            let lang = if let Some(ref ls) = lang_str {
                language::resolve_lang(ls).unwrap()
            } else {
                detect::detect_language_from_file(&file_path)
            };

            let exit_code = executor::execute_file(&lang, &file_path);
            process::exit(exit_code);
        }
    } else {
        if is_stdin_tty() {
            let lang = lang_str.as_deref().and_then(|l| language::resolve_lang(l));
            repl::run_repl(lang);
        } else {
            let mut code = String::new();
            std::io::stdin().read_to_string(&mut code).unwrap_or(0);

            if code.is_empty() {
                return;
            }

            let lang = if let Some(ref ls) = lang_str {
                language::resolve_lang(ls).unwrap()
            } else if args.no_detect {
                language::Language::Python
            } else {
                detect::detect_language(&code)
            };

            let exit_code = executor::execute_stdin(&lang, &code);
            process::exit(exit_code);
        }
    }
}
