# The original: "1 + 2" in Perl mode -> stays Perl, prints 3
# My impl: "1 + 2" in Perl mode -> auto-detects to Python!

# The issue is my auto-detection is too aggressive
# When in Perl mode, "1 + 2" should stay Perl
# But my detect_language("1 + 2") returns Python (default)

# I need to understand when auto-detect should switch:
# The original only switches when the code STRONGLY matches another language
# For ambiguous code like "1 + 2" or "print \"hello\"", it stays in current language

# Looking at the original behavior:
# "print(\"hello\")" in Python mode -> switches to Lua (print( pattern)
# "1 + 2" in Perl mode -> stays Perl (no strong pattern match)
# "fn main(){}" in Python mode -> switches to Rust (fn main pattern)

# The key: the auto-detect should only switch when it STRONGLY detects another language
# For the default/Python fallback, it should NOT switch

# I need to update the REPL to only auto-detect when the detected language is NOT the default (Python)

python3 << 'PYEOF'
with open('/workspace/src/repl.rs', 'r') as f:
    content = f.read()

old_detect = '''        // Auto-detect
        if auto_detect {
            let detected = detect_language(input);
            if detected != current_lang {
                println!("[auto-detect] switching {} \\u{{2192}} {}", current_lang.name(), detected.name());
                current_lang = detected;
                session = ReplSession::new(&current_lang);
            }
        }'''

new_detect = '''        // Auto-detect: only switch if strongly detected (not Python default)
        if auto_detect {
            let detected = detect_language(input);
            // Only switch if:
            // 1. The detected language is different from current
            // 2. The detected language is not the default fallback (Python)
            //    UNLESS current language is already Python (then switching to non-Python makes sense)
            let should_switch = detected != current_lang && (
                !matches!(detected, Language::Python) || 
                matches!(current_lang, Language::Python)
            );
            if should_switch {
                println!("[auto-detect] switching {} \\u{{2192}} {}", current_lang.name(), detected.name());
                current_lang = detected;
                session = ReplSession::new(&current_lang);
            }
        }'''

content = content.replace(old_detect, new_detect)

with open('/workspace/src/repl.rs', 'w') as f:
    f.write(content)

# Also need to add Language import
if 'use crate::language::Language;' not in content:
    content = content.replace('use crate::language::Language;', 'use crate::language::Language;')

print("Done!")
PYEOF
```

