# Progress! "1 + 2" now returns "3" and stays in Perl mode!
# But there are "Useless use of a constant in void context" warnings!
# This is because the previous statements (like "1 + 2") are being evaluated again
# as part of the cumulative session, but their result is now discarded

# The issue: my session wraps "1 + 2" in result printing:
# `my $__r = do { 1 + 2 }; print $__r, "\n" if defined($__r);`
# But in subsequent runs, the SAME expression gets re-evaluated (in the cumulative file)
# and the "1 + 2" now just evaluates in void context (result discarded)

# The fix: when adding previous statements to the session file,
# they should be added WITHOUT the result-printing wrapper
# Only the CURRENT (last) statement should have the result printing

# Let me redesign the Perl REPL session structure:
# - Previous successful statements: stored as-is (no result printing)
# - Current statement: wrapped with result printing (only if not declaration)

# Actually the "Useless use" warnings come from Perl's strict mode
# The "1 + 2" expression in the cumulative file (without the result wrapper) is:
# "1 + 2" -> evaluates to 3, but result is discarded -> Perl warns "useless use"

# The fix: add `-W` flag (no warnings)? Or change the session structure?
# Actually the cleanest fix: previous statements should be wrapped in `do { ... }; `
# which discards the result without warning

# OR: use `# no warnings 'void';` in the file

# OR: just not have the previous evaluated results in the file at all
# Store previous statements differently

# Looking at the original Perl REPL:
# After "1 + 2" -> "3"
# After "my $x = 42" -> nothing
# After "$x * 2" -> "84"
# The "3" doesn't appear again when "$x * 2" is executed

# This means the session doesn't re-execute "1 + 2" when running "$x * 2"
# OR: it does but suppresses the warning

# Actually, I suspect the original stores previous results differently
# Perhaps the previous statements are run without warnings for subsequent runs
# Let me update to suppress warnings in previous statements

python3 << 'PYEOF'
with open('/workspace/src/repl.rs', 'r') as f:
    content = f.read()

old_exec_perl = '''    fn exec_perl(&mut self, input: &str) {
        let session_file = self.session_dir.join("session.pl");
        let mut content = String::from("use strict;\\nuse warnings;\\nuse Data::Dumper;\\n\\n");
        for s in &self.statements {
            content.push_str(s);
            if !s.trim_end().ends_with(';') { content.push(';'); }
            content.push('\\n');
        }

        // Check if statement is a declaration (no auto-print)
        let t = input.trim_start();
        let is_decl = t.starts_with("my ") || t.starts_with("my$") ||
                      t.starts_with("our ") || t.starts_with("local ") ||
                      t.starts_with("sub ") || t.starts_with("use ") ||
                      t.starts_with("package ");

        if is_decl {
            // Add statement as-is (no result printing)
            let stmt = if input.trim_end().ends_with(';') {
                input.to_string()
            } else {
                format!("{};", input)
            };
            content.push_str(&stmt);
        } else {
            // Wrap statement in result-printing code
            let stmt_body = if input.trim_end().ends_with(';') {
                input.trim_end_matches(';').to_string()
            } else {
                input.to_string()
            };
            content.push_str(&format!("my $__r = do {{ {} }}; print $__r, \\"\\\\n\\" if defined($__r);", stmt_body));
        }
        content.push('\\n');
        let _ = fs::write(&session_file, &content);

        match Command::new("perl").arg(&session_file).status() {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            _ => {}
        }
    }'''

new_exec_perl = '''    fn exec_perl(&mut self, input: &str) {
        let session_file = self.session_dir.join("session.pl");
        // Build session content
        // Previous statements stored with no-warnings for their re-execution
        let mut content = String::from("use strict;\\nuse warnings;\\nuse Data::Dumper;\\n\\n");
        for s in &self.statements {
            // Wrap previous statement in block to avoid void-context warnings
            let stmt = s.trim_end_matches(';');
            content.push_str("do { ");
            content.push_str(stmt);
            content.push_str(" };\\n");
        }

        // Check if statement is a declaration (no auto-print)
        let t = input.trim_start();
        let is_decl = t.starts_with("my ") || t.starts_with("my$") ||
                      t.starts_with("our ") || t.starts_with("local ") ||
                      t.starts_with("sub ") || t.starts_with("use ") ||
                      t.starts_with("package ");

        if is_decl {
            // Add statement as-is (no result printing)
            let stmt = if input.trim_end().ends_with(';') {
                input.to_string()
            } else {
                format!("{};", input)
            };
            content.push_str(&stmt);
        } else {
            // Wrap statement in result-printing code
            let stmt_body = if input.trim_end().ends_with(';') {
                input.trim_end_matches(';').to_string()
            } else {
                input.to_string()
            };
            content.push_str(&format!("my $__r = do {{ {} }}; print $__r, \\"\\\\n\\" if defined($__r);", stmt_body));
        }
        content.push('\\n');
        let _ = fs::write(&session_file, &content);

        match Command::new("perl").arg(&session_file).status() {
            Ok(s) if s.success() => {
                self.statements.push(input.to_string());
            }
            _ => {}
        }
    }'''

# Use simple find/replace with the marker
start = content.find('    fn exec_perl(&mut self, input: &str) {')
end = content.find('    fn exec_bash(&mut self, input: &str) {', start)
old_section = content[start:end]

content = content[:start] + new_exec_perl + '\n\n    ' + content[end:]

with open('/workspace/src/repl.rs', 'w') as f:
    f.write(content)
print("Done!")
PYEOF

